import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"量化选型","description":"","frontmatter":{"title":"量化选型","order":26},"headers":[],"relativePath":"ai/compute/kernel/quant_matrix.md","filePath":"ai/compute/kernel/quant_matrix.md"}`),a={name:`ai/compute/kernel/quant_matrix.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="量化方案选型矩阵" tabindex="-1">量化方案选型矩阵 <a class="header-anchor" href="#量化方案选型矩阵" aria-label="Permalink to “量化方案选型矩阵”">​</a></h1><p>选一张 4-bit 量化模型跑推理时，最常被问的问题是&quot;我这块卡到底该用哪个内核&quot;。答案不是看 GPU 显存够不够，而是看 GPU 架构代际——Ampere 起才开始有原生的 INT4 Tensor Core，Ada 起才有原生 FP8 Tensor Core，Blackwell 起才有原生 FP4。每张卡的最优内核完全不同。</p><p>本文以&quot;GPU 架构 × 量化方案&quot;的二维矩阵为主线，给出生产环境落地的选型决策树。</p><h2 id="位宽命名法" tabindex="-1">位宽命名法 <a class="header-anchor" href="#位宽命名法" aria-label="Permalink to “位宽命名法”">​</a></h2><p>在进入选型之前，必须先澄清一套贯穿整个行业的命名规则：W、A、FP 三种前缀分别代表什么。</p><p>W 和 A 后跟数字描述位宽。W 是 Weight（权重）的首字母，A 是 Activation（激活值）的首字母。例如 W4A16 表示权重 4-bit、激活 16-bit；W8A8 表示权重 8-bit、激活 8-bit。这是&quot;weight-only 量化&quot;（只压缩权重、激活保持高精度）和&quot;对等量化&quot;（权重和激活同等压缩）的核心区分。</p><p>FP 后跟数字表示浮点格式。例如 FP8 是 8-bit 浮点数（常见 E4M3 / E5M2 两种变体），FP16 / BF16 是 16-bit 浮点。FP8 不指定位宽，只指定数字格式——它既可以用于权重（写成 W8A8-FP8，权重和激活都用 FP8），也可以独立存在。</p><p>两者可以组合。W4A8-FP8 表示权重 4-bit 整数、激活 8-bit 浮点；NVFP4 是 NVIDIA 专为 Blackwell 设计的 4-bit 浮点格式（用微块缩放 + E4M3 scale）。理解了这套命名规则，所有量化方案的&quot;是什么&quot;问题就回答了一半。</p><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>含义</th><th>典型硬件</th></tr></thead><tbody><tr><td>W4A16</td><td>量化方案</td><td>权重 INT4 + 激活 FP16/BF16</td><td>Ampere+</td></tr><tr><td>W8A8-FP8</td><td>量化方案</td><td>权重 FP8 + 激活 FP8</td><td>Ada/Hopper/Blackwell 原生</td></tr><tr><td>W4A8-FP8</td><td>量化方案</td><td>权重 INT4 + 激活 FP8</td><td>Hopper（CUTLASS）</td></tr><tr><td>NVFP4</td><td>量化格式</td><td>4-bit 浮点 + 微块缩放</td><td>Blackwell 原生</td></tr></tbody></table><h2 id="选型决策矩阵" tabindex="-1">选型决策矩阵 <a class="header-anchor" href="#选型决策矩阵" aria-label="Permalink to “选型决策矩阵”">​</a></h2><p>把 GPU 架构代际和量化方案画成一张二维表，就是这张矩阵的全部内容。每一格代表&quot;在该架构上跑该量化方案时，使用什么后端、性能如何、推荐度怎样&quot;。</p><table tabindex="0"><thead><tr><th>GPU 架构</th><th>计算能力</th><th>最优内核</th><th>备选内核</th><th>不推荐内核</th><th>推荐格式</th></tr></thead><tbody><tr><td>Blackwell 数据中心（B200）</td><td>sm_100</td><td>CUTLASS NVFP4 + DeepGEMM</td><td>FP8</td><td>Marlin（性能次优）</td><td>NVFP4 优先</td></tr><tr><td>Blackwell 消费级（RTX 5090）</td><td>sm_120</td><td>CUTLASS NVFP4 SM120 + TensorRT-Edge-LLM</td><td>FP8</td><td>Marlin（性能次优）</td><td>NVFP4 优先</td></tr><tr><td>AMD RDNA3（RX 7900 XTX）</td><td>gfx1100</td><td>vLLM Native W4A16</td><td>HybridW4A16</td><td>NVFP4（无原生）</td><td>AWQ / GPTQ (W4A16)</td></tr><tr><td>AMD CDNA4（MI355X）</td><td>gfx950</td><td>NVFP4 → MXFP4 在线重量化</td><td>MXFP6+MXFP4 混合</td><td>NVFP4 原生（无硬件）</td><td>NVFP4 checkpoint / MXFP4</td></tr><tr><td>AMD 跨平台</td><td>多代</td><td>HybridW4A16 (Triton + HIP skinny)</td><td>—</td><td>—</td><td>AWQ 通用 fallback</td></tr><tr><td>Hopper（H100 / H200）</td><td>sm_90</td><td>FP8 原生</td><td>Machete / CUTLASS W4A8</td><td>Marlin（已被 Machete 替代）</td><td>FP8 优先，W4A8 备选</td></tr><tr><td>Ada Lovelace（RTX 4090 / L40S）</td><td>sm_89</td><td>FP8 原生</td><td>Marlin</td><td>CUTLASS W4A8（为 Hopper 设计）</td><td>FP8 优先，AWQ/GPTQ 备选</td></tr><tr><td>Ampere（RTX 3090 / A100）</td><td>sm_80 / sm_86</td><td>Marlin</td><td>W8A8 INT8</td><td>FP8（无硬件支持，会回退）</td><td>AWQ / GPTQ (W4A16)</td></tr><tr><td>Turing（RTX 2080 Ti / T4）</td><td>sm_75</td><td>无现代内核，llama.cpp Q4_K_M</td><td>bitsandbytes INT8 / vLLM Marlin SM75 fork</td><td>FP8（无硬件支持）</td><td>Q4_K_M / IQ4_XS</td></tr><tr><td>Volta（V100）</td><td>sm_70</td><td>无现代内核，llama.cpp Q4_K_M 唯一可靠路径</td><td>1Cat-vLLM fork (AWQ) / vllm-fp8-w8a16-sm70</td><td>NVFP4（fallback 到 12% 带宽）</td><td>Q4_K_M</td></tr></tbody></table><p>每一行的推荐内核都依赖该架构的某项硬件能力，盲目套用别的架构的最优解会得到非常差的结果。</p><h3 id="ampere-marlin-是绝对主力" tabindex="-1">Ampere：Marlin 是绝对主力 <a class="header-anchor" href="#ampere-marlin-是绝对主力" aria-label="Permalink to “Ampere：Marlin 是绝对主力”">​</a></h3><p>Ampere 没有原生 FP8 Tensor Core——任何 FP8 模型在 Ampere 上都会回退到 W8A16 模式（FP8 权重用 Marlin FP8 内核反量化），损失原 FP8 的吞吐优势。Ampere 上 INT4 推理的最优内核只有 Marlin，其他备选（W8A8 INT8、ExLlamaV2）在中等 batch 的服务场景下吞吐显著低于 Marlin。</p><p>启动配置：vLLM 中 AWQ/GPTQ 模型默认走 Marlin 后端。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">awq-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awq_marlin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gptq-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gptq_marlin</span></span></code></pre></div><p>ExLlamaV2 在 batch=1 的单用户极致延迟场景下可能反超 Marlin，但一旦进入多用户合并 batch 就被 Marlin 拉开差距。Marlin 的关键技术细节（异步内存拷贝、Tensor Core 融合反量化）见 <a href="./marlin">Marlin</a>。</p><h3 id="ada-lovelace-marlin-和-fp8-原生" tabindex="-1">Ada Lovelace：Marlin 和 FP8 原生 <a class="header-anchor" href="#ada-lovelace-marlin-和-fp8-原生" aria-label="Permalink to “Ada Lovelace：Marlin 和 FP8 原生”">​</a></h3><p>Ada 是首个消费级原生支持 FP8 Tensor Core 的架构（第四代）。FP8（W8A8）在精度几乎无损的前提下，吞吐和显存效率都比 Marlin 加速的 W4A16 更好——前提是显存够用。显存紧张时（4090 24G 跑 13B+ 模型）退回 Marlin + AWQ/GPTQ。</p><p>启动配置：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># FP8 优先</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fp8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kv-cache-dtype</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fp8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 显存不够时退回 Marlin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">awq-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awq_marlin</span></span></code></pre></div><p>Ada 上 FP8 的优化成熟度仍略逊于 Hopper，但已经可用且效果不错。Ada 没有原生 FP4，强行使用 NVFP4 只会模拟、没有硬件加速收益。</p><h3 id="hopper-fp8-最成熟-machete-替代-marlin" tabindex="-1">Hopper：FP8 最成熟，Machete 替代 Marlin <a class="header-anchor" href="#hopper-fp8-最成熟-machete-替代-marlin" aria-label="Permalink to “Hopper：FP8 最成熟，Machete 替代 Marlin”">​</a></h3><p>Hopper 的 FP8 支持是当前数据中心部署的事实标准。第四代 Tensor Core + Transformer Engine + FA3 让 FP8 推理的性能和精度都达到生产级。如果坚持使用 W4A16，应该选 Machete（Marlin 在 Hopper 上的继任者，针对 wgmma + TMA 优化），而不是继续用 Marlin——Marlin 没有针对 Hopper 的新指令集做优化，在 H100 上性能远不如 Machete。</p><p>启动配置：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># FP8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fp8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kv-cache-dtype</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fp8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># W4A16 走 Machete 而非 Marlin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">awq-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awq_marlin</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # vLLM 会自动选 Machete</span></span></code></pre></div><p>Hopper 还支持 CUTLASS W4A8（INT4 权重 + FP8 激活），用于同时追求低显存和高计算吞吐。<code>CutlassW4A8LinearKernel</code> 要求 compute capability ≥ 90 且不支持 zero-point 和 act-order。</p><h3 id="blackwell-nvfp4-多源分化" tabindex="-1">Blackwell：NVFP4 多源分化 <a class="header-anchor" href="#blackwell-nvfp4-多源分化" aria-label="Permalink to “Blackwell：NVFP4 多源分化”">​</a></h3><p>Blackwell 第五代 Tensor Core 原生支持 FP4，NVFP4 是 NVIDIA 专为它设计的 4-bit 浮点格式——用微块缩放 + E4M3 scale，精度接近 FP8 但显存和速度比 INT4 还激进。这是当前生产部署的最前沿，B200 和 RTX 5090 都应该优先考虑 NVFP4。</p><p>启动配置：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvfp4</span></span></code></pre></div><p>与 W4A16 有 Marlin 这个社区主导的“杀手级内核”不同，NVFP4 目前由多个源头的算子拼接而成，还没有一个一统天下的名字。SM100（数据中心）和 SM120（消费级）走完全不同的指令路径，两者不能混用。</p><h4 id="sm100-数据中心-b200-路径" tabindex="-1">SM100（数据中心 B200）路径 <a class="header-anchor" href="#sm100-数据中心-b200-路径" aria-label="Permalink to “SM100（数据中心 B200）路径”">​</a></h4><p>数据中心 Blackwell B200 / B100 / GB200 走 <code>tcgen05.mma</code> block-scaled 指令，这是为数据中心推理全新设计的 5 代 Tensor Core 指令。</p><p>指令特性：</p><ul><li><code>tcgen05.mma</code> 接受 block-scaled 输入（权重 + 微块缩放因子同时送入）</li><li>累加器存在专门的 TMEM（Tensor Memory），不是传统寄存器或 SMEM——带宽更高、压力更小</li><li>TMA（Tensor Memory Accelerator）从 Hopper 传承下来，负责大规模异步数据搬运</li><li>输出可以是 FP32 / BF16 / FP8，下游 GEMM 可以接任何精度</li></ul><p>CUTLASS 参考实现：<code>examples/72_blackwell_narrow_precision_gemm/72b_blackwell_nvfp4_nvfp4_gemm.cu</code>。这是 NVIDIA 官方给出的性能基准点。</p><p>DeepGEMM（DeepSeek-AI 出品）走相同的 SM100 路径，专为 MoE / grouped-GEMM 场景优化，是当前 FP4 推理吞吐最高的选择之一。截至 2026 初仍 SM100-only，SM120 移植正在进行中。如果在 B200 上跑 MoE（如 DeepSeek-V3 / Qwen-MoE），DeepGEMM 是首选。</p><h4 id="sm120-消费级-rtx-5090-路径" tabindex="-1">SM120（消费级 RTX 5090）路径 <a class="header-anchor" href="#sm120-消费级-rtx-5090-路径" aria-label="Permalink to “SM120（消费级 RTX 5090）路径”">​</a></h4><p>消费级 RTX 5090 / RTX 50 系移动版 走 <code>mma.sync.aligned.block_scale</code> 指令——名字里还能看到 <code>mma.sync</code>，说明这是从 Ampere 传承下来的指令家族，不是数据中心卡的全新 <code>tcgen05</code>。这是因为消费级 Blackwell 缺少 TMEM 和大规模 TMA 路径，本质上是“带着 FP4 Tensor Core 的 Ampere”。</p><p>指令差异：</p><ul><li>没有 TMEM——累加器还是回到寄存器 / SMEM</li><li>没有完整的 TMA 异步搬运能力，数据搬运走传统 <code>cp.async</code></li><li><code>mma.sync.aligned.block_scale</code> 是 SM 8.0+ 都能编译的指令家族（不一定只在 SM120），但 FP4 Tensor Core 仅 SM120+ 有</li></ul><p>CUTLASS 参考实现：<code>examples/79_blackwell_geforce_gemm/79a_blackwell_geforce_nvfp4_bf16_gemm.cu</code>（单 GEMM）+ <code>79d_blackwell_geforce_nvfp4_grouped_gemm.cu</code>（MoE 用 grouped 变体）。注意文件名里的 <code>bf16</code>——SM120 NVFP4 的反量化目标默认是 BF16，不是 NVFP4↔NVFP4（SM100 那个路径）。</p><p>TensorRT-Edge-LLM 仓库里有 CuTe DSL 写的 <code>blockscaled_contiguous_grouped_gemm_finalize_fusion.py</code>，专门给 SM120 上的 MoE FP4 推理用。这是当前消费级 Blackwell 上 MoE FP4 的最高性能实现。</p><p>吞吐量参考（仅来自 CUTLASS example 头部声明，未独立验证）：</p><ul><li>NVFP4 比 MXFP8 MMA 快 ~2 倍</li><li>NVFP4 比 Ada Tensor Core 快 ~4 倍</li><li>这些数字仅适用于 SM120 上的 FP4 路径</li></ul><h4 id="两路径对比" tabindex="-1">两路径对比 <a class="header-anchor" href="#两路径对比" aria-label="Permalink to “两路径对比”">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>SM100 (B200)</th><th>SM120 (RTX 5090)</th></tr></thead><tbody><tr><td>MMA 指令</td><td><code>tcgen05.mma</code>（全新 5 代）</td><td><code>mma.sync.aligned.block_scale</code>（Ampera 家族延续）</td></tr><tr><td>累加器</td><td>TMEM</td><td>寄存器 + SMEM</td></tr><tr><td>数据搬运</td><td>完整 TMA</td><td><code>cp.async</code>（传统异步加载）</td></tr><tr><td>CUTLASS 路径</td><td><code>72_blackwell_narrow_precision_gemm</code></td><td><code>79_blackwell_geforce_gemm</code></td></tr><tr><td>DeepGEMM 支持</td><td>✅ SM100-only 主力</td><td>❌ 移植进行中</td></tr><tr><td>TensorRT-Edge-LLM</td><td>⚠️ 主供 SM120</td><td>✅ CuTe DSL 主供 SM120 MoE</td></tr><tr><td>反量化输出</td><td>FP32 / BF16 / FP8</td><td>默认 BF16</td></tr></tbody></table><p>反量化在所有 Blackwell NVFP4 路径上都发生在 Tensor Core 内部，没有独立的“dequant kernel”——这与 Marlin 的设计一致（避免写回全局内存），但实现机制不同：Marlin 在寄存器里反量化，Blackwell 的 NVFP4 直接在 Tensor Core 的微块缩放电路里完成。</p><p>Marlin 在 Blackwell 上不是不能跑，但性能远不如 NVFP4——Blackwell 的 wgmma + TMA + FP4 Tensor Core 路径没有被 Marlin 利用起来。如果在 Blackwell 上继续用 Marlin + W4A16，相当于在 5nm 工艺的卡上跑 8nm 时代的优化思路，硬件潜力只发挥了一小部分。</p><h3 id="volta-与-turing-老卡的现实处境" tabindex="-1">Volta 与 Turing：老卡的现实处境 <a class="header-anchor" href="#volta-与-turing-老卡的现实处境" aria-label="Permalink to “Volta 与 Turing：老卡的现实处境”">​</a></h3><p>Volta（V100，sm_70）和 Turing（RTX 20 系、T4，sm_75）在 2026 年这个时间点跑 LLM 没有任何“高效”算子可选。这不是缺工具，而是硬件能力断档太多：缺 BF16 硬件支持、缺 FlashAttention-2（要 sm_80+）、缺 <code>cp.async</code>（Marlin 类优化都跑不了）。但仍有几个降级方案能“勉强跑起来”。</p><p>Turing (sm_75):</p><ul><li>llama.cpp + Q4_K_M / IQ4_XS | 上游支持 | 不走 Tensor Core 加速，CUDA 后端走 ggml 通用 GEMM |</li><li>bitsandbytes LLM.int8() (INT8) | 上游支持 | INT8 路径，不是 INT4 |</li><li>vLLM Marlin SM75 后端 | 实验性 fork（PR #29901） | 没有 <code>cp.async</code>，用同步 GMEM→SMEM；没有 m16n8k16，要 m16n8k8 串两次凑齐 K=16 |</li><li>fused-int4-gemm-sm75（独立项目） | 第三方 | 手写 PTX INT4 GEMM，用 WMMA + mma.sync.aligned，已验证 Qwen2 可跑 |</li></ul><p>Volta (sm_70):</p><ul><li>llama.cpp + Q4_K_M | 上游支持 | Volta 没有 INT4 Tensor Core，CUDA 后端走初代 FP16 Tensor Core |</li><li>1Cat-vLLM fork | 实验性 | 集成 lmdeploy TurboMind SM70 WMMA 内核，能跑 AWQ 4-bit |</li><li>vllm-fp8-w8a16-sm70 | 第三方 fork | 跑 FP8 W8A16，反量化权重到 FP16；改善 decode 但不是原生加速 |</li><li>NVFP4 | ⚠️ 严重回退 | V100 上 NVFP4 自动 fallback 到 Marlin dequant，仅达显存带宽的 12% |</li><li>vLLM 上游 pip wheels | ⚠️ 已放弃 | 需要从源码编译（CUDA 12.6）才能跑 vLLM |</li></ul><p>实际推荐：两张老卡的唯一可靠路径都是 llama.cpp + Q4_K_M——不依赖 Tensor Core、社区维护最稳、跨平台。B200 路上重起炉灶的 Marlin SM75 fork 、vllm-fp8-w8a16-sm70 、fused-int4-gemm-sm75 都处于“能跑但性能不惊人”的状态，不要指望它们能接近主流 30/40 系的体验。T4 上一个 benchmark 报告 INT4 量化在 ~4000 tok/s 平台，FP16 + 投机解码反而能跑到 9000 tok/s——在某些负载下量化不是吞吐赢家。</p><p>跳过所有现代内核（FA2、Marlin、NVFP4、FP8）后，长上下文和 BF16 模型会非常慢。建议 Turing 跑 Q4_K_M 4-bit 量化模型（避开 BF16 fallback），V100 跑 Q4_K_M 并接受它的吞吐——这是老卡唯一现实的部署方案。</p><h3 id="amd-三条路线分开走" tabindex="-1">AMD：三条路线分开走 <a class="header-anchor" href="#amd-三条路线分开走" aria-label="Permalink to “AMD：三条路线分开走”">​</a></h3><p>AMD 的量化生态不如 NVIDIA 成熟，但 2026 年已经形成三条可用的内核路径，分别面向消费级 RDNA、数据中心 CDNA、以及跨平台量化 checkpoint。三者走的不是同一套指令。</p><h4 id="消费级-rdna3-rx-7900-xtx-w7900" tabindex="-1">消费级 RDNA3（RX 7900 XTX / W7900） <a class="header-anchor" href="#消费级-rdna3-rx-7900-xtx-w7900" aria-label="Permalink to “消费级 RDNA3（RX 7900 XTX / W7900）”">​</a></h4><p>RDNA3 没有原生的 INT4 Tensor Core（AMD 的 Matrix Core 支持 FP16 / BF16 / INT8，不包含 INT4），但社区在 vLLM 里逐步补上了 W4A16 的高效实现。</p><p>Native W4A16 kernel for RDNA3（vLLM PR #41394）：在 gfx1100（RX 7900 XTX）上跑 GPTQ-W4A16-G32 模型，官方 benchmark 报告在所有测试的并发度上都超过现有 ROCm 选项（包括 ExLlama 的 ROCm 后端），且原生支持 BF16——ExLlama 此前不支持 BF16。测试用 Qwen3.6-27B-GPTQ-W4A16-G32 在双卡 RX 7900 XTX、并发 100 下进行。</p><p>启动配置（vLLM）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">awq-or-gptq-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awq</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 自动选 RDNA3 native W4A16</span></span></code></pre></div><p>注意：RDNA4（RX 9070 系）这条路径尚未在社区调查中明确报道，但与 RDNA3 架构同源，预计类似实现能顺接。</p><h4 id="数据中心-cdna-mi300x-mi355x" tabindex="-1">数据中心 CDNA（MI300X / MI355X） <a class="header-anchor" href="#数据中心-cdna-mi300x-mi355x" aria-label="Permalink to “数据中心 CDNA（MI300X / MI355X）”">​</a></h4><p>数据中心 Instinct 卡走 CDNA 架构，有原生 FP8、MXFP4、MXFP6 硬件支持，但不直接支持 NVFP4——这是与 NVIDIA Blackwell 的关键差异点。</p><p>MXFP4 与 MXFP6：AMD 在 MI350X / MI355X 上原生支持 MXFP4（OCP Microscaling 4-bit 浮点）。MXFP6 激活 + MXFP4 权重（W_MXFP4_A_MXFP6）的混合精度在 Llama-3.1-8B 和 Qwen3.6-2x 上报告能恢复部分 MXFP4 损失的精度，且吞吐仅比纯 MXFP4 慢 2-3%。</p><p>NVFP4 on AMD：NVFP4 是 NVIDIA 专有格式，AMD 在 MI350X/MI355X 上原生只能算 MXFP4，不能直接跑 NVFP4。AMD 的解决方案是在线重量化（NVFP4 → MXFP4）——加载 NVFP4 checkpoint 时自动转成 MXFP4 跑，不需预转换。这让 AMD 可以消费 NVIDIA 生态的现成 NVFP4 模型（HF 上 amd/DeepSeek-V4-Flash-NVFP4、amd/Qwen3.5-397B-A17B-NVFP4 都是 AMD 发布的 NVFP4 checkpoint），但损失一点吞吐。</p><p>W4A16 GEMM（vLLM Issue #34008 / PR #42640）：早期 vLLM 在 AMD 上缺乏高性能 W4A16 GEMM 和 grouped GEMM，后续 CDNA 调优版本补齐。</p><p>启动配置：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># MI355X 上跑 NVFP4 checkpoint（自动 requant 到 MXFP4）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> amd/DeepSeek-V4-Flash-NVFP4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quantization</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvfp4</span></span></code></pre></div><h4 id="hybrid-w4a16-rocm-跨架构" tabindex="-1">Hybrid W4A16（ROCm 跨架构） <a class="header-anchor" href="#hybrid-w4a16-rocm-跨架构" aria-label="Permalink to “Hybrid W4A16（ROCm 跨架构）”">​</a></h4><p>vLLM PR #40977 推出了 HybridW4A16LinearKernel，这个路径不针对特定架构，而是把两种实现拼起来：</p><ul><li>小 batch（M ≤ 5，单 token decode）：走 HIP 手写的 <code>wvSplitK_int4_g</code> skinny decode 路径，专门优化小矩阵乘</li><li>大 batch（M &gt; 5，prefill 和多 token decode）：走 Triton fused dequant GEMM</li></ul><p>两条路径共用同一份 AWQ 风格打包的 <code>[N, K//8]</code> 权重张量，不需要双份存储。这是 ROCm 生态里一个比较通用的 W4A16 优化范式——它不依赖特定硬件（不论 CDNA 还是 RDNA 都能跑），但跨架构性能不是每张卡都是最优。</p><h4 id="实际推荐" tabindex="-1">实际推荐 <a class="header-anchor" href="#实际推荐" aria-label="Permalink to “实际推荐”">​</a></h4><table tabindex="0"><thead><tr><th>AMD 硬件</th><th>推荐路径</th><th>启动参数</th></tr></thead><tbody><tr><td>RX 7900 XTX / W7900 (gfx1100)</td><td>vLLM native W4A16 (PR #41394)</td><td><code>--quantization awq</code> 或 <code>gptq</code></td></tr><tr><td>MI300X (CDNA3)</td><td>FP8 原生 / W4A16 CDNA-tuned</td><td>按模型选</td></tr><tr><td>MI355X / MI350X (CDNA4)</td><td>NVFP4 → MXFP4 在线重量化</td><td><code>--quantization nvfp4</code></td></tr><tr><td>MI355X 质量优先</td><td>MXFP6 激活 + MXFP4 权重混合</td><td>依赖现成 quantized checkpoint</td></tr><tr><td>AMD 全平台</td><td>HybridW4A16（PR #40977）</td><td>通用 fallback</td></tr></tbody></table><p>关键限制：AMD 没有 Marlin 这样的“社区一统”内核。生态仍处于“多个 PR 多条路径”的阶段，上游 vLLM 主线在 AMD 上的优化成熟度还低于 NVIDIA 1-2 年。如果你选了 AMD 卡（特别是消费级），就要准备踩踩、跑跑社区 fork。</p><h2 id="为什么不能跨架构套用" tabindex="-1">为什么不能跨架构套用 <a class="header-anchor" href="#为什么不能跨架构套用" aria-label="Permalink to “为什么不能跨架构套用”">​</a></h2><p>很多用户在选型时会犯&quot;看别人跑得好就直接抄&quot;的错误。常见的反面教材：</p><p>用 FP8 权重跑在 Ampere 上——Ampere 没有原生 FP8 Tensor Core，FP8 权重会被自动反量化到 FP16 再做矩阵乘法，吞吐甚至不如直接用 FP16 + Marlin 的 W4A16 路径。FP8 模型在 Ampere 上不是&quot;快&quot;，而是&quot;绕了一圈变慢&quot;。</p><p>用 Marlin 跑在 Hopper 上——Marlin 是为 Ampere 的 cp.async 设计的，没有用到 Hopper 的 wgmma + TMA 新指令。同一个 W4A16 模型在 H100 上用 Marlin 跑，比用 Machete 跑慢 30%-50%。</p><p>用 NVFP4 跑在 Ada 上——Ada 没有原生 FP4 Tensor Core，NVFP4 会被软件模拟。损失精度的同时，吞吐也不如直接用原生 FP8。NVFP4 必须配 Blackwell。</p><p>每个量化方案的&quot;原生硬件&quot;是它在设计阶段就锚定的，跨架构使用就失去了硬件加速的根基。选型的第一步永远是先看 GPU 架构代际，第二步才是看模型有什么量化版本。</p><h2 id="决策树简化" tabindex="-1">决策树简化 <a class="header-anchor" href="#决策树简化" aria-label="Permalink to “决策树简化”">​</a></h2><p>如果上面的矩阵看着累，可以按以下三步快速决策。</p><p>第一步：确认 GPU 架构。<code>nvidia-smi</code> 查看 GPU 型号，对照 NVIDIA 官方架构图确认是 Ampere / Ada / Hopper / Blackwell 中哪一个。如果是 Volta 或 Turing（A100 之前、RTX 20 系及更早），直接放弃跑现代大模型——BF16 和 FlashAttention-2 都缺失，强行跑只会得到 NaN 输出和长文本卡顿。</p><p>第二步：在该架构的最优内核列里选。Ampere → Marlin + W4A16；Ada → FP8（W8A8）优先；Hopper → FP8 或 Machete；Blackwell → NVFP4。如果该架构上没有原生的最优格式，退回到 Marlin 通用方案。</p><p>第三步：根据显存调整。如果最优格式的模型权重加上 KV Cache 超过显存，降到次优格式（通常是 W4A16 系）。如果是 batch=1 的单用户极致延迟场景，可以试试 ExLlamaV2 系（EXL2/EXL3 格式），它在 Ampere/Ada 上有小 M 场景的速度优势。</p><h2 id="与其他量化内核的关系" tabindex="-1">与其他量化内核的关系 <a class="header-anchor" href="#与其他量化内核的关系" aria-label="Permalink to “与其他量化内核的关系”">​</a></h2><p>这张矩阵之外，还有两个常被提及的内核值得单独说明。</p><p>EXL2（ExLlamaV2 专用）是 2~8 bit 混合比特的私有格式，权重存储和 Marlin 期望的 GPTQ/AWQ 布局完全不同——EXL2 模型不能直接用 Marlin 跑，反之亦然。EXL2 在 batch=1 的单用户场景下 decode 速度往往领先 Marlin，但在多用户合并 batch 的服务场景下退路较少。如果你的工作负载是个人本地推理，EXL2 + ExLlamaV2 是优秀选择；如果是多用户服务，AWQ/GPTQ + Marlin 更稳妥。</p><p>GGUF（llama.cpp 原生格式）是 CPU+GPU 混合推理的瑞士军刀——<code>ngl</code> 参数控制多少层放 GPU、多少层走 CPU 内存。GGUF 不属于本文讨论的 GPU 内核选型范畴，但在显存放不下完整模型、系统内存足够时是决定性能力。GGUF 与 Marlin/FP8 是正交关系——前者是部署架构选择，后者是 GPU 内核选择。</p><h2 id="工程实践要点" tabindex="-1">工程实践要点 <a class="header-anchor" href="#工程实践要点" aria-label="Permalink to “工程实践要点”">​</a></h2><p>vLLM 默认会自动选最优后端。AWQ/GPTQ 模型在 Ampere 上默认走 Marlin，在 Hopper 上默认走 Machete，在 Blackwell 上会优先 NVFP4。手动指定 <code>--quantization awq_marlin</code> 是为了显式锁定，避免框架版本升级时默认行为变化。</p><p>Group size 选 128。Marlin 的反量化流水线和 group-wise scale 都围绕 128 这个粒度优化。64 / 256 等其他值虽然能跑，但性能通常略低。</p><p>KV Cache 量化是独立维度。本文讨论的是权重量化，KV Cache 量化（FP8 KV Cache、TurboQuant 等）是独立的优化维度，与权重方案可以叠加使用——例如 FP8 权重 + FP8 KV Cache 是 Ada/Hopper 的常见生产配置。</p><p>精度与吞吐的权衡。W4A16 的精度损失通常在 1-3%（大模型更小），W8A8-FP8 精度几乎无损。如果业务对精度极其敏感（如金融、医疗），优先 FP8 而不是 W4A16；如果只是聊天/写作/代码辅助，W4A16 已经足够。</p>`,101)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};